def is_good(n):
    s = str(n)
    if len(s) == 1:
        return True

    digits = [int(d) for d in s]

    # Check all removals
    for i in range(len(digits)):
        temp_s = s[:i] + s[i+1:]
        if not temp_s:
            continue

        d = int(temp_s)

        # Check divisibility
        if n % d == 0:
            # Check if the resulting divisor d is also good
            if is_good(d):
                return True
    return False

