def get_digits(n):
    return n // 10, n % 10

def check_candidate(a, d, G2_list):
    """
    Checks if m = 100*a + d is a good number when removing 'a' results in 'd'.
    'd' must be in G2_list.
    a, b, c must be distinct.
    """
    b, c = get_digits(d)

    # Check distinctness
    if a == b or a == c or b == c:
        return False, "Digits not distinct"

    # Check if d is good (already handled by iterating over G2, but good for safety)
    if d not in G2_list:
        return False, "d is not good"

    # Check divisibility
    m = 100 * a + d
    if m % d == 0:
        return True, f"m = {m}, d = {d}, m/d = {m//d}"
    else:
        return False, f"m = {m}, d = {d}, not divisible"

